files.content:
:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #f0f0f0;
  --muted: #a0a0b0;
  --correct: #4ecca3;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--accent);
  border-radius: 0;
  padding: 32px 24px;
  max-width: 420px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.4);
}

h1 {
  font-size: 1.5rem;
  margin: 0 0 16px;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.question {
  font-size: 1.75rem;
  font-weight: bold;
  margin: 24px 0;
  min-height: 2.5rem;
  word-break: break-word;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin-bottom: 24px;
}

button {
  font-family: inherit;
  font-size: 1.25rem;
  padding: 12px 24px;
  min-width: 80px;
  border: 3px solid var(--accent);
  background: transparent;
  color: var(--text);
  cursor: pointer;
  border-radius: 0;
  transition: background 0.1s, transform 0.1s;
}

button:hover:not(:disabled) {
  background: var(--accent);
  color: var(--bg);
}

button:focus-visible {
  outline: 3px solid var(--text);
  outline-offset: 3px;
}

button:active:not(:disabled) {
  transform: translate(2px, 2px);
}

button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

button.correct {
  background: var(--correct);
  border-color: var(--correct);
  color: var(--bg);
}

button.wrong {
  background: var(--accent);
  border-color: var(--accent);
  color: var(--bg);
}

.score-line {
  font-size: 1.25rem;
  margin: 0 0 24px;
  color: var(--muted);
}

#score {
  color: var(--accent);
  font-weight: bold;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
}

@media (max-width: 400px) {
  .card { padding: 24px 16px; }
  .answers { flex-direction: column; align-items: center; }
  button { width: 100%; }
  .controls { flex-direction: column; }
}

const state = {
  questionIndex: 0,
  score: 0,
  locked: false,
  questions: [
    { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
    { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
  ]
};

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

function render() {
  const q = state.questions[state.questionIndex];
  if (!q) {
    questionEl.textContent = 'Finished';
    answerA.style.display = 'none';
    answerB.style.display = 'none';
    nextBtn.disabled = true;
    return;
  }
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.style.display = '';
  answerB.style.display = '';
  scoreEl.textContent = String(state.score);
  answerA.disabled = false;
  answerB.disabled = false;
  answerA.classList.remove('correct', 'wrong');
  answerB.classList.remove('correct', 'wrong');
  nextBtn.disabled = true;
  state.locked = false;
}

function selectAnswer(choice) {
  if (state.locked) return;
  state.locked = true;
  const q = state.questions[state.questionIndex];
  const correctBtn = choice === 'a' ? answerA : answerB;
  const wrongBtn = choice === 'a' ? answerB : answerA;
  if (q.correct === choice) {
    state.score += 1;
    correctBtn.classList.add('correct');
    wrongBtn.classList.add('wrong');
  } else {
    correctBtn.classList.add('wrong');
    wrongBtn.classList.add('correct');
  }
  scoreEl.textContent = String(state.score);
  answerA.disabled = true;
  answerB.disabled = true;
  nextBtn.disabled = false;
}

function next() {
  if (state.questionIndex < state.questions.length - 1) {
    state.questionIndex += 1;
    render();
  } else {
    state.questionIndex += 1;
    render();
  }
}

function restart() {
  state.questionIndex = 0;
  state.score = 0;
  state.locked = false;
  render();
}

answerA.addEventListener('click', () => selectAnswer('a'));
answerB.addEventListener('click', () => selectAnswer('b'));
nextBtn.addEventListener('click', next);
restartBtn.addEventListener('click', restart);

render();
